<script setup lang="ts">import { ref } from 'vue';import { api,post } from '../../api/client';import AsyncState from '../../components/AsyncState.vue';type Stage='quality-and-detect'|'residuals-and-consistency'|'materialize-evidence'|'hypotheses'|'check-plans';type Product='quality'|'anomalies'|'residuals'|'consistency-observations'|'evidence'|'symptoms'|'evidence-timeline'|'hypotheses'|'causal-subgraph'|'check-plan';const props=defineProps<{initialRun?:string}>(),runId=ref(props.initialRun??''),product=ref<any>(),error=ref(''),loading=ref(false);async function stage(path:Stage,body:any={}){loading.value=true;error.value='';try{product.value=await post(`/runs/${runId.value}/${path}`,body)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}async function load(path:Product){loading.value=true;try{product.value=await api(`/runs/${runId.value}/${path}`)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}</script>
<template><section class="panel"><div class="panel-head"><div><h2>Diagnosis pipeline</h2><p>Every conclusion retains source references, quality, transformation, and digest.</p></div><input v-model="runId" placeholder="run_id"></div><div class="toolbar"><button class="secondary" @click="stage('quality-and-detect')">Quality & detect</button><button class="secondary" @click="load('evidence')">Evidence</button><button class="secondary" @click="stage('hypotheses')">Rank hypotheses</button><button class="secondary" @click="stage('check-plans')">Propose checks</button></div><AsyncState :loading="loading" :error="error" :empty="!product"><pre>{{product}}</pre></AsyncState></section></template>
